const response = $input.first().json;
const data = $('Prepare Infographic Data1').first().json;

// Extract base64 image from OpenAI response
const b64 = response.data[0].b64_json;
const binary = Buffer.from(b64, 'base64');

return [{
  json: {
    filename: data.filename,
    niche: data.niche,
    automationType: data.automationType,
    caption: data.caption,
    timestamp: data.timestamp,
    remaining: data.remaining
  },
  binary: {
    data: {
      data: binary,
      mimeType: 'image/png',
      fileName: data.filename
    }
  }
}];

const industries = $('Get Industries List1').all().map(i => ({
  sector: i.json['Sector'],
  niche: i.json['Industry / Niche']
})).filter(i => i.niche);

const automations = $('Get Automation Types1').all().map(a => ({
  type: a.json['Automation Type'],
  desc: a.json['What It Does']
})).filter(a => a.type);

const posted = $('Get Post Tracker1').all().map(p => ({
  niche: p.json['Industry / Niche'],
  automation: p.json['Automation Type']
})).filter(p => p.niche && p.automation);

const usedCombos = new Set(posted.map(p => `${p.niche}|||${p.automation}`));

let attempts = 0, selectedIndustry = null, selectedAutomation = null, combo = '';
while (attempts < 500) {
  const ri = industries[Math.floor(Math.random() * industries.length)];
  const ra = automations[Math.floor(Math.random() * automations.length)];
  combo = `${ri.niche}|||${ra.type}`;
  if (!usedCombos.has(combo)) { selectedIndustry = ri; selectedAutomation = ra; break; }
  attempts++;
}
if (!selectedIndustry) throw new Error('All combinations exhausted after 500 attempts.');

const promptText = `You are a senior AI automation consultant writing a LinkedIn post on behalf of SmartFlow Lab — a UK-based AI automation studio.\n\nWrite a LinkedIn post about how ${selectedAutomation.type} can transform a ${selectedIndustry.niche} business.\n\nRules:\n- 150-200 words maximum\n- Write like a human practitioner, not a marketer\n- Open with a specific pain point this business type faces (not a generic opener)\n- Explain briefly how automation solves it (1-2 sentences, no technical jargon)\n- Include one realistic outcome or result (e.g. '3 hours saved per day', '40% fewer no-shows')\n- End with a soft CTA\n- Do NOT use hashtags\n- Do NOT mention SmartFlow Lab by name in the post body\n- Do NOT use em dashes\n- Do NOT start with 'I'\n\nIndustry: ${selectedIndustry.niche}\nSector: ${selectedIndustry.sector}\nAutomation type: ${selectedAutomation.type}\nWhat it does: ${selectedAutomation.desc}`;

return [{ json: {
  sector: selectedIndustry.sector,
  niche: selectedIndustry.niche,
  automationType: selectedAutomation.type,
  automationDesc: selectedAutomation.desc,
  combo,
  promptText: promptText.replace(/[\n\r]/g, ' ').replace(/"/g, '\\"'),
  totalIndustries: industries.length,
  totalAutomations: automations.length,
  totalUsed: posted.length,
  remaining: (industries.length * automations.length) - posted.length - 1
} }];

